from typing import List, Tuple
from collections import defaultdict
from itertools import permutations

class TreeGraph:
    def __init__(self, n: int):
        self.n = n
        self.graph = [None] * n
        self.degrees = [0] * n

    def add_edge(self, u: int, v: int):
        nodes = [u, v]
        for node in nodes:
            if node >= self.n:
                raise ValueError("Nodes must be within the range of n")
            if self.graph[node] is None:
                self.graph[node] = []
            self.graph[node].append(nodes[0 ^ 1])

    def chocolate_buckets(self) -> int:
        visited = [False] * self.n
        paths = [0] * self.n

        for i in range(self.n - 1):
            u, v = self.graph[i]
            deg = 1
            seen = set([u, v])

            while paths[u] != paths[v]:
                for node in [u, v]:
                    if path := paths[node]:
                        deg += path
                    if not (nodes := self.graph[node]):
                        self.graph[node] = []
                        break

                if deg > self.n // 2:
                    break

                visited[node] = True
                paths[u] = paths[v] + 1
                visited[v] = True
                paths[v] = paths[u] + 1
                seen.update(seen)
                while len(seen) < i + 2:
                    del seen[-1]

        for node in range(self.n):
            if not visited[node]:
                # Isolated node -> some paths start from it
                counts = 0
                for node in range(self.n):
                    start_node = node
                    count = 0
                    while start_node == node:
                        # path
                        start_node = nodes[0 ^ 1]
                        count += path
                    if nodes[start_node] == node:
                        counts += count

                # between, starts from me
                counts -= paths[node]
                paths[node] = counts
                seen.add(node)

            if paths[node] == 1:
                break

            paths[node] = paths[node] // 2

        return reduce(lambda x, y: x * y % 1000000007, paths, 1)

    def is_balanced(self) -> int:
        visited = [False] * self.n
        paths = [0] * self.n

        for i in range(self.n - 1):
            u, v = self.graph[i]
            deg = 1
            seen = set()

            while paths[u] != paths[v]:
                for node in [u, v]:
                    path = paths[node] != paths[u]
                    if not (nodes := self.graph[node]):
                        self.graph[node] = []
                        break

                    if bits := path & (nodes[0] ^ nodes[1]):
                        deg += path ^ bits
                        deg %= 1000000007

                    if nodes[1] == node or bits:
                        seen.update([[node, i], [nodes[0], path]])
                        break

            seen.add((nodes[0], paths[u]))

        balanced = 0
        for path, _ in seen:
            balanced += paths[path]

        return balanced % 1000000007

def solve(n: int, edges: List[Tuple[int, int]], a: List[int]) -> int:
    tgraph = TreeGraph(n)
    for u, v in edges:
        tgraph.add_edge(u - 1, v)

    chocolate_buckets = tgraph.chocolate_buckets()
    if chocolate_buckets:
        deg_arr = [degrees := nodes[0] ^ nodes[1] for nodes in edges]
        degrees += [tuple(degrees)]
    else:
        deg_arr = [[0 for _ in range(n)] for _ in range(n)]

    unique_degrees_map = {tuple(a): list(b) for a, b in enumerate(deg_arr)}
    deg_to_order = defaultdict(list)
    for a, b in unique_degrees_map:
        deg_to_order[a].append((b, degrees[b]))

    l_buckets = len(deg_to_order[min(deg_to_order.keys())])
    buckets = []
    buckets += [tuple(a, b, c) for a, b in deg_to_order.values() if a != l_buckets - 1 or b]

    for i, bucket in enumerate(buckets):
        deg = bucket[:2]
        bgs = bucket[2] + 1
        next_bgs = max(deg)

        if next_bgs == bgs:
            _, bgs += -1
            deg_bgs = min(deg_to_order[:-1])
        deg_bgs = min(max(deg_bgs) + 1, l_buckets)
        deg_bgs += 1
        deg_bgs = deg_bgs if deg_bgs <= l_buckets else deg
        deg_bgs -= 1
        while deg_bgs == deg and bgs < l_buckets - 1:
            break

        if deg_bgs + bgs + buckets[0][-2] < deg:
