        self.n = n
        self.graph = defaultdict(list)

    def add_edge(self, u, v):
        self.graph[u].append(v)
        self.graph[v].append(u)

    def dfs(self, node, visit):
        visit.add(node)
        for neighbor in self.graph[node]:
            if neighbor not in visit:
                self.dfs(neighbor, visit)
        return visit

    def dfs_num(self, node, res):
        visit = set()
        for neighbor in self.graph[node]:
            if neighbor not in visit:
                visit = self.dfs(neighbor, visit)
                res -= 1
            else:
                res += 1
        return visit

    def dfs_swap(self, i, swap_r):
        visit = self.dfs(i)
        num_peoples = len(self.dfs_num(i, 0))
        num_pos = len(self.dfs_num(i, 1))

        if num_peoples ==  i and num_pos == res-1:
            return 1

        return 0

