from math import ceil

MOD = 10**9 + 7

class BinarySearch:
    def __init__(self, arr):
        self.arr = arr
        self.n = len(arr)
        self.prefix_sum = [0] * (self.n + 1)
        self.increment_decrease = [0] * (self.n + 1)

        for i in range(1, self.n + 1):
            self.prefix_sum[i] = self.prefix_sum[i-1] + arr[i-1]

    def find_next(self, x):
        i = bisect_right(self.arr, x) 
        if i == 0 or self.arr[i-1] != x:
            return None
        return self.prefix_sum[i-1]

    def find_next_index(self, x):
        i = bisect_right(self.arr, x) 
        if i == self.n or self.arr[i-1] != x:
            return None
        return self.prefix_sum[i-1]

    def inc(self, k):
        x = self.prefix_sum[k]
        c = self.find_next(x)
        if c is not None:
            self.increment_decrease[k] += c
            self.prefix_sum[k] = c
