def get_shortest_path(map, n, m, k):
    graph = [[[float('inf') for _ in range(k+1)] for _ in range(m)] for _ in range(n)]
    start = ('S')
    first_end = ('T')
    # T can be the end including cases of empty path.
    graph[0][0][k] = 0

    def bfs(start, end, k, map):
        queue = deque([(0, 0, k)])
        while queue:
            dist, i, j, types_left = queue.popleft()

            if i == n-1 and j == m-1:
                if dist < graph[i][j][k]:
                    graph[i][j][k] = dist
                continue

            if map[i][j] in ('S', start, end):
                continue

            # R0: skip S types.
            if types_left > 0 and map[i][j] != start:
                graph[i][j][k] = min(graph[i][j][k], dist + 1)
                graph[i][j][k+1] = min(graph[i][j][k+1], dist + 1)

            # R1: visit (1 new) type the first time.
            if graph[i][j][k] > dist + 1 and map[i][j] != start:
                graph[i][j][k+1] = min(graph[i][j][k+1], dist + 1)

            # R2: visit a type that you've visited before; you can repeat each.
            if map[i][j] != start and graph[i][j][k] == dist + 1:
                types_left -= 1

            # R3: visit a type that you've visited before; you are still allowed to visit each infinite number of times.
            for di in range(2):
                if map[i + di][j] in ['S', start, end]:
                    continue
                if graph[i + di][j] > graph[i][j] + 1:
                    graph[i + di][j] = graph[i][j]
                    graph[i + di][j][k] = graph[i][j][k]
                if types_left:
                    graph[i + di][j][k+1] = min(graph[i + di][j][k+1], graph[i][j][k])
                types_left += 1

            for ii in range(4):
                if map[i][j + ii] in ['S', start, end]:
                    continue
                if graph[i][j + ii] > graph[i][j] + 1:
                    graph[i][j + ii] = graph[i][j]
                    graph[i][j + ii][k] = graph[i][j][k]
                if types_left:
                    graph[i][j + ii][k+1] = min(graph[i][j + ii][k+1], graph[i][j][k])
                types_left += 1

            queue.append((dist + 1, i + 1, j, types_left))

    # S first: for each place where you can skip it, try it.
    bfs('S', start, 0, map)
    # Map is traversed two times, because of repeated types (for ith type only):
    bfs(start, end, k, map)
    bfs('T', end, 0, map)

    for i in range(n):
        for j in range(m):
            if graph[i][j][k] == float('inf'):
                graph[i][j][k] = ''
            else:
                graph[i-1][j][k] = graph[i][j][k]

    while not ((m-1) - graph[-1][-1][k], graph[-1][-1][k] == 0) or not ((n-1) - graph[-1][-1][k], graph[-1][-1][k] == 0):
        if m-1 - graph[-1][-1][k] or n-1 - graph[-1][-1][k] or graph[-1][-1][k] == '':
