def min_operations(A, B):
    dp = defaultdict(int)
    dp[A[0]] = (0, 0)

    for i in range(1, len(A)):
        directions = defaultdict(int)
        for key, val in dp.items():
            j = i - 1
            while j >= 0 and (j + 1) % 2 == i % 2:
                j -= 1
            directions[j] = (j + 1, max(0, key + min(3, A[j + 1] - key)))

        for key, val in dp.items():
            key1, val1 = key + 1, val[0] + 1
            key2, val2 = key + 3, val[0] + 2
            if key2 in directions:
                dp[key] = (max(dp[key1]), directions[key2][0])
            else:
                dp[key] = (min(dp[key2]), max(val1, directions[key1][0]))

    if 0 in dp and dp[0][1] <= len(B):
        return dp[0][1]
    else:
        return -1

