            r, c = stack.popleft()
            if grid[r][c] == 'T':
                if len(path) < k + 1:
                    path += grid[r][c]
                break

            for dr, dc in directions:
                nr, nc = r + dr, c + dc
                if 0 <= nr < n and 0 <= nc < m and (nr, nc) not in moved and (nr, nc) not in visited:
                    visited.add((nr, nc))
                    moved.add((nr, nc))
                    stack.append((nr, nc))

        else:
            if path == '':
                return "-1\n" if len(moved) == 0 else path
            else:
                path = min(path, ''.join(sorted(grid[move[0]][move[1]].lower() if (move[0], move[1]) in moved else '' for move in moved))[-k:])
                for move in moved:
                    grid[move[0]][move[1]] = 'S'
                visited = set()
                moved = set()
                if len(path) == k + 1:
                    return "-1\n" if len(moved) == 0 else path

    return path

