from heapq import heappush, heappop

def dijkstra(grid, start, end, visited, dist):
    heap = [(0, start, "")]
    while heap:
        distance, node, path = heappop(heap)
        if node == end and len(path) > 0:
            min_path = path + (str(grid[end[0]][end[1]]),)
            min_path = "".join(sorted(min_path))
            min_path = min_path.split("S") if "S" in min_path else list("S" + min_path)
            min_path = min_path.pop().split("T")
            min_path = "".join(sorted(min_path))
            return min_path
        for nei in get_neighbors(grid, node):
            visit, empty, time, type_ = visited[nei], 1 if "S" in grid[nei] else 0, dist[node][nei], grid[nei] if type_ else ""
            if (visit, empty) not in visited or dist[nei][visit] > distance + time + 1 - empty:
                visited[nei] = (visit, empty, time if type_ else 0, type_)
                dist[nei][visit] = distance + time + 1 - empty
                heappush(heap, (distance + time + 1, nei, path + (type_,)))
    return -1

def get_neighbors(grid, node):
    xs, ys = range(len(grid[0])), range(len(grid))
    return [(x, y) for y in ys for x in xs if abs(node[0] - y) + abs(node[1] - x) == 1]

def solve(n, m, k, grid):
    if "T" not in ("".join(grid)):
        return "-1"
    dist, visited = [[defaultdict(int, dist[0][1])] * (n+1) for _ in range(m+1)], {start: (1, 1, 1, 1) for start in start_pos}
    for i in range(len(grid)):
        visited[i][1] = (1, 0, 1, 1)
        for j in range(1, len(grid[0])):
            visited[i][j] = (1, j, 0 if "S" in grid[i][j] else (0, -1), "")
    path = dijkstra(grid[1:-1], grid[0], grid[-1], visited, dist)
    return "-1" if not path else path

