from collections import Counter
from typing import List, Tuple

class SmellerQueue:
    def __init__(self):
        self.queue = []
        self.count = Counter()

    def push(self, num: int) -> None:
        while self.queue and self.queue[-1] > num:
            self.queue.pop()
        self.queue.append(num)
        self.count[num] += 1

    def pop(self, num: int) -> None:
        if self.count[num] == 1:
            self.queue.pop()
        self.count[num] -= 1

    def mex(self) -> int:
        return next(iter(self.count.keys()))

def update_new_queue(smeller_queue: SmellerQueue, l, r) -> None:
    while l > 0:
        l -= 1
        smeller_queue.pop(smeller_queue.mex())
    while r < len(smeller_queue.queue):
        r += 1
        smeller_queue.push(smeller_queue.mex())
    while r > l + 1:
        l += 1
        smeller_queue.pop(smeller_queue.mex())

def get_mex(num: int, smeller_queue: SmellerQueue):
    while True:
        if smeller_queue.count[num] == 0:
            return -1
        else:
            smeller_queue.pop(num)
            smeller_queue.push(-1)

def mex_queries(a: List[int], q: List[Tuple[int, int, int]]) -> List[int]:
    n, q = len(a), len(q)
    smeller_queue = SmellerQueue()
    ans = [0] * q
    for i, l, r in q:
        if i == 1:
            update_new_queue(smeller_queue, l, r)
        else:
            ans[i-1] = get_mex(smeller_queue.mex(), smeller_queue)
    return ans

