        i, x = q.popleft()
        if x + 1 < m:
            l = i * (x + 1)
            cur = filter(lambda x: x + 1 >= l, [x, x + 1])
            for y in cur:
                if not dist[y]: dist[y] = l
                q.append((y, l))

