import math

def can_rebalance(nums, res):
    target_sum = sum(res) / len(res)
    box_sums = [sum(res[i][1] for i in range(len(res))) for res in reversed(res)]
    for i in range(len(res)):
        res[i][1] = [num + target_sum for num in box_sums[i]]
    return sum(box_sums) == sum(res)

def find_sorted_indices(sums, x):
    if not x:
        return []
    idxs = [i[1] for i in sorted(range(len(sums)), key=lambda j: sums[j])]
    if len(sums) % 2:
        if x % 2:
            return idxs[-2::]
        else:
            return idxs[-1::]
    else:
        if x % 2:
            return idxs[-2::]
        else:
            return idxs[-2::-2]

def find_possibilities(nums):
    results = [[0 for _ in range(len(nums[i]))] for i in range(len(nums))]
    for i in range(len(results)):
        for n in nums[i]:
            results[i][results[i].index(-n)] = 1 if n > 0 else -1
        results[i] = [i + 1 for i, v in enumerate(results[i]) if v == 1]
    return results

def solve(k, nums):
    n = [0] * k
    res = ['' for _ in range(k)]
    for i in range(k):
        n[i] = len(nums[i]) - 1
        nums[i].pop(-1)
    for r in find_possibilities(nums):
        sums = [sum(r[i]) for i in range(len(nums))]
        ss = list(reversed(sums))
        if can_rebalance(ss, r):
            for i in range(k):
