def find_largest_beauty(n, brackets):
    max_beauty = 0
    max_beauty_indices = [0, 0]

    def is_valid_shift(shift):
        stack = deque()
        balance = 0
        for i in range(n):
            bracket = (i + shift) % n
            if brackets[brackets[i]]:
                if balance == 0:
                    balance += 1
                else:
                    balance -= 1
            else:
                if balance == 0:
                    balance -= 1
                else:
                    balance += 1

                if balance == 0:
                    stack.append(i)

                while stack and balance != 0:
                    if brackets[brackets[stack.pop()]]:
                        if balance == 0:
                            balance -= 1
                        else:
                            balance += 1
                    else:
                        if balance == 0:
                            balance -= 1
                        else:
                            balance += 1

                        if balance == 0:
                            stack.append(brackets[stack.pop()])

            if balance == 0:
                break

        return len(stack) == n

    for i in range(n):
        for j in range(i + 1, n):
            if is_valid_shift(j - i):
                beauty = (i + 1) + (n - i - j) + 1
                if beauty > max_beauty:
                    max_beauty = beauty
                    max_beauty_indices = [i, j]

    return max(max_beauty, 0), max_beauty_indices[0] + 1, max_beauty_indices[1] + 1


