from collections import defaultdict

def build_prefix_function(s):
    n = len(s)
    pi = [0] * n
    for i in range(1, n):
        j = pi[i - 1]
        while j > 0 and s[i] != s[j]:
            j = pi[j - 1]
        if s[i] == s[j]:
            j += 1
        pi[i] = j
    return pi

def kmp_match(s, t, pi):
    n = len(s)
    m = len(t)
    j = 0
    for i in range(n):
        while j > 0 and s[i] != t[j]:
            j = pi[j - 1]
        if s[i] == t[j]:
            j += 1
        if j == m:
            return i - j + 1
    return -1

def hamming_distance(a, b):
    return ''.join('1' if ch1 != ch2 else '0' for ch1, ch2 in zip(a, b)).count('1')

def solve():
    a = input().strip()
    b = input().strip()
    q = int(input())
    queries = []
    for _ in range(q):
        piA, piB = defaultdict(int), defaultdict(int)
        queries.append(tuple(map(int, input().strip().split())))
        for p1, p2, len_ in queries:
            if len_ >= 1:
                piA[p1:p1+len_] = build_prefix_function(a[p1:p1+len_])
            if len_ >= 1:
                piB[p2:p2+len_] = build_prefix_function(b[p2:p2+len_])
    for p1, p2, len_ in queries:
        if len_ >= 1:
            distance = hamming_distance(a[p1:p1+len_], b[p2:p2+len_])
        else:
            distance = hamming_distance(a[:len_], b[:len_])
        print(distance)

if __name__ == "__main__":
    solve()
