from itertools import tee, islice

def pairwise(iterable):
    a, b = tee(iterable)
    next(b, None)
    return zip(a, b)

def dot_product(A, B, x, y, l):
    dot_product = 0
    for a, b in pairwise(A):
        if 0 <= x + l - 1 < N and 0 <= y + l - 1 < N:
            dot_product += A[x + l - 1] * B[y + l - 1]
    return dot_product

